contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller) public payable {
        address ownerBefore = c.owner();
        bool reverted;
        if (caller == ownerBefore) {
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.owner() == newOwner);
        } else {
            // Simulate a call from a non-owner by a direct call? Can't change msg.sender.
            // Since msg.sender is fixed to this contract, we can only test owner path.
            // To make a general rule, we need to handle both cases. But we cannot change msg.sender.
            // Instead, we can use the fact that if caller != ownerBefore, the setOwner call would revert,
            // but we cannot trigger that here because msg.sender is this contract.
            // We test the owner path, but the rule must be general. We can assert that if we call setOwner
            // with any newOwner, since we are the owner, it succeeds and owner becomes newOwner.
            // To make it general, we can note that the only way to call setOwner is from this contract,
            // which is the owner. So the rule is: when called by the owner, setOwner always succeeds and updates owner.
            // However, this doesn't cover non-owner revert. To include non-owner, we would need to control msg.sender,
            // which is not possible. So we restrict to the case where caller == ownerBefore, and assert success and update.
            // But the property says "a general rule that P satisfies for ALL inputs". If we only test owner case,
            // we can still assert a general rule: for any newOwner, if the caller is the owner, then setOwner succeeds
            // and owner becomes newOwner. But the checker runs once with arbitrary inputs. Since msg.sender is always
            // this contract, the caller is always the owner. So the rule should be: setOwner always succeeds and updates owner.
            // But wait, the contract has a modifier onlyOwner that requires msg.sender == owner. Since msg.sender is
            // this contract, and this contract deployed c, owner is this contract. So setOwner always succeeds.
            // We can simplify: call c.setOwner(newOwner); assert(c.owner() == newOwner);
            // However, the rule must be general and not depend on msg.sender? But msg.sender is fixed.
            // We'll just do the call and assert that owner is updated.
            c.setOwner(newOwner);
            assert(c.owner() == newOwner);
        }
    }

    receive() external payable {}
}

