contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        // Capture the caller (which is this test contract) and the original owner
        address caller = msg.sender;
        address originalOwner = c.owner();

        bool reverted;
        bool success;
        try c.setOwner(newOwner) returns (bool _success) {
            success = _success;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: If the call completed, then it returned true and:
        //   - if the caller was the owner, owner is now newOwner
        //   - otherwise, owner is unchanged (still originalOwner)
        assert(
            reverted
            || (success
                && (caller == originalOwner ? c.owner() == newOwner : c.owner() == originalOwner))
        );
    }

    receive() external payable {}
}

