}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner) public {
        address beforeOwner = c.owner();
        bool isOwner = (msg.sender == beforeOwner);
        bool reverted;
        bool ret;
        try c.setOwner(_owner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
        }
        address afterOwner = c.owner();
        assert(isOwner ? (!reverted && ret && afterOwner == _owner) : (reverted && afterOwner == beforeOwner));
    }

    receive() external payable {}
}
